 g=goals[gid];tid=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://skillpilot.com/assessment/physics/2026-11-15/'+slug));dims=copy.deepcopy(g['dimensionTags']);dims.update(demandLevel='AB3',processCompetencies=['PK2_MODELLIEREN','PK3_MATHEMATISIEREN','PK4_KOMMUNIZIEREN'],guidingIdeas=['LI_WELLEN','LI_TECHNIK'],topicCode='CANONICAL.PHYSICS.PRACTICE.'+slug.upper().replace('-','_'))
