# Normalize prose spacing; preserve decimal commas in DE and distinguish vector lists.
def prose(v,field=''):
 if isinstance(v,dict):return {k:prose(w,k) for k,w in v.items()}
 if isinstance(v,list):return [prose(w,field) for w in v]
 if not isinstance(v,str) or field not in {'title','titleEn','description','descriptionEn','taskContent','taskContentEn','solutionContent','solutionContentEn','reviewNote'}:return v
 protected=[]
 def hold(m):
  token='\ue000'+chr(0xe100+len(protected))+'\ue001';protected.append((token,m.group(0)));return token
 v=re.sub(r'https?://[^\s)]+|/assets/[^\s)]+',hold,v)
 if field in {'taskContent','solutionContent'}:v=re.sub(r'\((-?\d+),(-?\d+),(-?\d+)\)',r'(\1; \2; \3)',v)
 v=re.sub(r'([A-Za-zÄÖÜäöüß])(?=\d)',r'\1 ',v)
 v=re.sub(r'(\d)(?=[A-Za-zÄÖÜäöüß])',r'\1 ',v)
 v=re.sub(r',(?=[A-Za-zÄÖÜäöüß])',', ',v)
 v=re.sub(r'(?<=[A-Za-zÄÖÜäöüß]),(?=\S)',', ',v)
 for token,original in protected:v=v.replace(token,original)
 return v
tasks=prose(tasks)
(B/'content-candidate.json').write_text(json.dumps({'status':'AUTHOR_CANDIDATES_REQUIRING_INDEPENDENT_CONTENT_REVIEW','tasks':tasks},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'newTaskIds':[t['id'] for t in tasks],'wholeGoalIds':[t['requires'][0] for t in tasks],'scoring':[(t['examData']['scoring']['maxPoints'],t['examData']['scoring']['passingPoints']) for t in tasks]}))
